// The absolute simplest concept of Redux in plain JavaScript:

let state = { count: 0 };

// You don't do this:
// state.count = 5; (Unpredictable! Anyone can do this anywhere!)

// You do this:
function updateState(currentState, request) {
  if (request.type === 'ADD') {
    return { count: currentState.count + 1 };
  }
  return currentState;
}
